-- Referência do esquema base (já aplicado na D1 aquipay-db). Não voltar a executar.
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, city TEXT, phone TEXT, bio TEXT, avatar_key TEXT, professions_json TEXT NOT NULL DEFAULT '[]', skills_json TEXT NOT NULL DEFAULT '[]', portfolio_json TEXT NOT NULL DEFAULT '[]', experience_json TEXT NOT NULL DEFAULT '[]', education_json TEXT NOT NULL DEFAULT '[]', resume_key TEXT, intro_video_key TEXT, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), public_profile INTEGER NOT NULL DEFAULT 1 CHECK(public_profile IN (0,1)));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE wallets (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, available_coins INTEGER NOT NULL DEFAULT 0 CHECK(available_coins >= 0), pending_coins INTEGER NOT NULL DEFAULT 0 CHECK(pending_coins >= 0), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE wallet_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, amount_coins INTEGER NOT NULL CHECK(amount_coins <> 0), reference TEXT, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('pending','posted','reversed')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE listings (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('job','product','service')), title TEXT NOT NULL, description TEXT NOT NULL, price_minor INTEGER, currency TEXT NOT NULL DEFAULT 'AOA', city TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','closed','removed')), media_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE proposals (id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id), sender_id TEXT NOT NULL REFERENCES users(id), receiver_id TEXT NOT NULL REFERENCES users(id), message TEXT NOT NULL, price_minor INTEGER, currency TEXT NOT NULL DEFAULT 'AOA', delivery_days INTEGER, status TEXT NOT NULL DEFAULT 'sent' CHECK(status IN ('sent','accepted','rejected','withdrawn','completed','cancelled')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE conversations (id TEXT PRIMARY KEY, proposal_id TEXT REFERENCES proposals(id), participant_a TEXT NOT NULL REFERENCES users(id), participant_b TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK(participant_a <> participant_b));
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', read_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE profile_ratings (id TEXT PRIMARY KEY, target_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reviewer_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5), comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(target_user_id,reviewer_user_id), CHECK(target_user_id <> reviewer_user_id));
CREATE TABLE documents (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, category TEXT NOT NULL CHECK(category IN ('cv','certificate','portfolio','experience','education','intro_video')), original_name TEXT NOT NULL, content_type TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, size_bytes INTEGER NOT NULL CHECK(size_bytes > 0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN (0,1)));
CREATE UNIQUE INDEX idx_conversation_pair ON conversations(proposal_id, participant_a, participant_b);
CREATE INDEX idx_documents_user ON documents(user_id,created_at DESC);
CREATE INDEX idx_listings_feed ON listings(status, created_at DESC);
CREATE INDEX idx_listings_owner ON listings(owner_id, created_at DESC);
CREATE INDEX idx_messages_conversation ON messages(conversation_id, created_at DESC);
CREATE INDEX idx_notifications_unread ON notifications(user_id, read_at, created_at DESC);
CREATE INDEX idx_profile_ratings_target ON profile_ratings(target_user_id,created_at DESC);
CREATE INDEX idx_proposals_receiver ON proposals(receiver_id, status, created_at DESC);
CREATE INDEX idx_proposals_sender ON proposals(sender_id, created_at DESC);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX idx_sessions_user ON sessions(user_id);
